enum { PORT_PLAYER_STATE_FACES = 175, PORT_PLAYER_STATE_CELLS = 185 };

static int (__fastcall *port_player_state_face_for(unsigned rom))(void *, void *)
{
    int lo = 0, hi = PORT_PLAYER_STATE_FACES - 1;
    while (lo <= hi) {
        const int mid = (lo + hi) / 2;
        const unsigned at = g_pmf3_player_state_faces[mid].rom;
        if (at == rom)
            return g_pmf3_player_state_faces[mid].face;
        if (at < rom)
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    return 0;
}

/* Once per process, after __sinit_ov002_021019d0 has filled the objects and
   before the first Player exists: hal_fill_player_vtable (the registry
   install) and tests/smoke_player.cpp's own bring-up both call it. A second
   call is a no-op, the PowerStar seat's shape. Every cell is checked against
   the ROM's table first: a word that differs refuses the boot (the SignPost
   seat's shape); a null cell the ROM fills is left null, as the dispatch saw
   it before this seat, and said once. */
extern "C" void port_player_states_seat(void)
{
    static int done;
    if (done)
        return;
    done = 1;
    int seated = 0, unfilled = 0;
    for (int i = 0; i < (int)(sizeof g_player_states / sizeof g_player_states[0]); ++i) {
        for (int k = 0; k < 3; ++k) {
            PortPmfCell *c = &g_player_states[i]->cell[k];
            if (c->code == 0) {
                if (g_player_state_rom[i][k] != 0) {
                    ++unfilled;
                    std::fprintf(stderr, "[pmf3] Player state object %d cell %d: "
                                 "the ROM fills it with %08x, the sinit left it "
                                 "null here; left null\n", i, k,
                                 g_player_state_rom[i][k]);
                }
                continue;
            }
            int (__fastcall *face)(void *, void *) =
                port_player_state_face_for(c->code);
            if (!face || c->code != g_player_state_rom[i][k] || c->adjust != 0) {
                std::fprintf(stderr, "FATAL: Player state object %d cell %d holds "
                             "%08x/%d, the ROM's table says %08x/0 -- WRONG "
                             "BYTES\n", i, k, c->code, c->adjust,
                             g_player_state_rom[i][k]);
                std::abort();
            }
            c->code = (unsigned)(size_t)face;
            ++seated;
        }
    }
    if (seated + unfilled != PORT_PLAYER_STATE_CELLS) {
        std::fprintf(stderr, "FATAL: seated %d Player state cells and found %d "
                     "null, the ROM fills %d\n", seated, unfilled,
                     PORT_PLAYER_STATE_CELLS);
        std::abort();
    }
}
